import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalN = scanner.nextInt();
        int totalK = scanner.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < totalK; i++) {
            int x = scanner.nextInt();
            v[x] = 1;
        }
        int[] resultPoly = {1};
        int halfPower = totalN / 2;
        while (halfPower > 0) {
            if ((halfPower & 1) == 1) {
                resultPoly = polyMultiply(resultPoly, v, 998244353);
            }
            v = polyMultiply(v, v, 998244353);
            halfPower >>= 1;
        }
        long sumSquares = 0;
        for (int val : resultPoly) {
            sumSquares += (long) val * val;
        }
        System.out.println(sumSquares % 998244353);
    }

    static int[] polyMultiply(int[] a, int[] b, int mod) {
        int size = 1;
        while (size < a.length + b.length - 1) size <<= 1;
        double[] A = new double[size];
        double[] B = new double[size];
        for (int i = 0; i < a.length; i++) A[i] = a[i];
        for (int i = 0; i < b.length; i++) B[i] = b[i];
        fftTransform(A, false);
        fftTransform(B, false);
        for (int i = 0; i < size; i++) A[i] *= B[i];
        fftTransform(A, true);
        int[] result = new int[a.length + b.length - 1];
        for (int i = 0; i < result.length; i++) {
            result[i] = (int) Math.round(A[i]) % mod;
        }
        return result;
    }

    static void fftTransform(double[] a, boolean invert) {
        int n = a.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j >= bit; bit >>= 1) {
                j -= bit;
            }
            j += bit;
            if (i < j) {
                double temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            double angle = 2 * Math.PI / len * (invert ? -1 : 1);
            double wlenCos = Math.cos(angle);
            double wlenSin = Math.sin(angle);
            for (int i = 0; i < n; i += len) {
                double wCos = 1;
                double wSin = 0;
                for (int j = 0; j < len / 2; j++) {
                    int u = i + j;
                    int v = i + j + len / 2;
                    double uVal = a[u];
                    double vVal = a[v] * wCos + a[v] * wSin;
                    a[u] = uVal + vVal;
                    a[v] = uVal - vVal;
                    double tempW = wCos;
                    wCos = wCos * Math.cos(angle) - wSin * Math.sin(angle);
                    wSin = wSin * Math.cos(angle) + tempW * Math.sin(angle);
                }
            }
        }
        if (invert) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
            }
        }
    }
}
